class MemberDirectory {
  #groups = [];
  #members = [];
  #groupIds = new Set();
  #memberIds = new Set();

  constructor(groups = [], members = []) {
    if (!Array.isArray(groups) || !Array.isArray(members)) throw new TypeError('arguments must be arrays');
    for (const group of groups) {
      const copy = MemberDirectory.#group(group);
      if (this.#groupIds.has(copy.id)) throw new RangeError('duplicate group id');
      this.#groupIds.add(copy.id);
      this.#groups.push(copy);
    }
    for (const member of members) {
      const copy = MemberDirectory.#member(member);
      if (this.#memberIds.has(copy.id)) throw new RangeError('duplicate member id');
      if (!this.#groupIds.has(copy.groupId)) throw new RangeError('unknown group id');
      this.#memberIds.add(copy.id);
      this.#members.push(copy);
    }
  }

  groups() { return this.#groups.map(group => ({ ...group })); }
  members() { return this.#members.map(member => ({ ...member })); }

  update(patch) {
    const copy = MemberDirectory.#member(patch);
    const index = this.#members.findIndex(member => member.id === copy.id);
    if (index < 0) throw new RangeError('unknown member id');
    this.#members[index] = copy;
    if (!this.#groupIds.has(copy.groupId)) throw new RangeError('unknown group id');
    return { ...copy };
  }

  details(id) {
    MemberDirectory.#string(id, 'id');
    const member = this.#members.find(item => item.id === id);
    if (!member) return null;
    const group = this.#groups.find(item => item.id === member.groupId);
    return { ...member, groupName: group.name };
  }

  static #exact(value, fields, name) {
    if (!value || typeof value !== 'object' || Array.isArray(value) || Object.getPrototypeOf(value) !== Object.prototype) throw new TypeError(name + ' must be plain');
    const keys = Object.keys(value).sort();
    const expected = [...fields].sort();
    if (keys.length !== expected.length || keys.some((key, i) => key !== expected[i])) throw new TypeError('invalid ' + name + ' fields');
  }

  static #string(value, name) {
    if (typeof value !== 'string' || value.length === 0) throw new TypeError(name + ' must be non-empty');
    return value;
  }

  static #group(value) {
    this.#exact(value, ['id', 'name'], 'group');
    return { id: this.#string(value.id, 'id'), name: this.#string(value.name, 'name') };
  }

  static #member(value) {
    this.#exact(value, ['id', 'name', 'age', 'pronoun', 'address', 'groupId'], 'member');
    if (!Number.isInteger(value.age)) throw new TypeError('age must be an integer');
    if (value.age < 0 || value.age > 130) throw new RangeError('age out of range');
    return {
      id: this.#string(value.id, 'id'),
      name: this.#string(value.name, 'name'),
      age: value.age,
      pronoun: this.#string(value.pronoun, 'pronoun'),
      address: this.#string(value.address, 'address'),
      groupId: this.#string(value.groupId, 'groupId')
    };
  }
}

module.exports = { MemberDirectory };

