'use strict';
const assert = require('node:assert');
const { MemberDirectory } = require('./solution');

assert.deepStrictEqual(Object.keys(require('./solution')), ['MemberDirectory']);
assert.deepStrictEqual(new MemberDirectory().groups(), []);
assert.deepStrictEqual(new MemberDirectory([], []).members(), []);

const groups = [{ id: 'g1', name: 'Engineering' }, { id: 'g2', name: 'Design' }];
const members = [{ id: 'm1', name: 'Asha', age: 0, pronoun: 'she/her', address: 'Bengaluru', groupId: 'g1' }];
const directory = new MemberDirectory(groups, members);
groups[0].name = 'Changed';
members[0].name = 'Changed';
assert.deepStrictEqual(directory.groups(), [{ id: 'g1', name: 'Engineering' }, { id: 'g2', name: 'Design' }]);
assert.deepStrictEqual(directory.members(), [{ id: 'm1', name: 'Asha', age: 0, pronoun: 'she/her', address: 'Bengaluru', groupId: 'g1' }]);
assert.deepStrictEqual(directory.details('m1'), {
  id: 'm1', name: 'Asha', age: 0, pronoun: 'she/her', address: 'Bengaluru', groupId: 'g1', groupName: 'Engineering'
});
assert.strictEqual(directory.details('unknown'), null);
assert.throws(() => directory.details(''), TypeError);

const returnedGroups = directory.groups();
const returnedMembers = directory.members();
returnedGroups[0].name = 'Mutated';
returnedMembers[0].address = 'Mutated';
assert.strictEqual(directory.groups()[0].name, 'Engineering');
assert.strictEqual(directory.members()[0].address, 'Bengaluru');

const patch = { id: 'm1', name: 'Asha P', age: 130, pronoun: 'she/her', address: 'Mysuru', groupId: 'g2' };
const updated = directory.update(patch);
patch.name = 'Caller mutation';
updated.name = 'Return mutation';
assert.deepStrictEqual(directory.members(), [{ id: 'm1', name: 'Asha P', age: 130, pronoun: 'she/her', address: 'Mysuru', groupId: 'g2' }]);
assert.strictEqual(directory.details('m1').groupName, 'Design');

const stable = directory.members();
assert.throws(() => directory.update({ ...stable[0], groupId: 'missing' }), RangeError);
assert.deepStrictEqual(directory.members(), stable);
assert.throws(() => directory.update({ ...stable[0], id: 'missing' }), RangeError);
assert.deepStrictEqual(directory.members(), stable);
assert.throws(() => directory.update({ ...stable[0], age: 131 }), RangeError);
assert.deepStrictEqual(directory.members(), stable);
assert.throws(() => directory.update({ ...stable[0], age: 1.5 }), TypeError);
assert.throws(() => directory.update({ ...stable[0], extra: true }), TypeError);

assert.throws(() => new MemberDirectory([{ id: 'g', name: 'G' }, { id: 'g', name: 'Other' }], []), RangeError);
assert.throws(() => new MemberDirectory([{ id: 'g', name: 'G' }], [
  { id: 'm', name: 'M', age: 1, pronoun: 'p', address: 'a', groupId: 'g' },
  { id: 'm', name: 'N', age: 2, pronoun: 'p', address: 'b', groupId: 'g' }
]), RangeError);
assert.throws(() => new MemberDirectory([], [{ id: 'm', name: 'M', age: 1, pronoun: 'p', address: 'a', groupId: 'g' }]), RangeError);
assert.throws(() => new MemberDirectory([{ id: '', name: 'G' }], []), TypeError);
assert.throws(() => new MemberDirectory([{ id: 'g', name: 'G', extra: 1 }], []), TypeError);
assert.throws(() => new MemberDirectory([Object.assign(Object.create({ x: 1 }), { id: 'g', name: 'G' })], []), TypeError);

